draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw a stick figure with a thought bubble
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 70);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 70);
  ctx.stroke();

  // thought bubble
  ctx.beginPath();
  ctx.arc(W/2, H/2 - 50, 30 + 10 * Math.sin(t), 0, 2 * Math.PI);
  ctx.stroke();

  // brain waves
  ctx.beginPath();
  ctx.moveTo(W/2 - 30, H/2 - 20);
  ctx.lineTo(W/2 - 30 + 20 * Math.sin(t), H/2 - 20 + 10 * Math.cos(t));
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/2 + 30, H/2 - 20);
  ctx.lineTo(W/2 + 30 + 20 * Math.cos(t), H/2 - 20 - 10 * Math.sin(t));
  ctx.stroke();

  ctx.restore();
}
